import random
import secrets
import string

HEX_LOWER = "0123456789abcdef"
HEX_UPPER = "0123456789ABCDEF"

def _rand_hex_digits(rng, n, upper=False):
    hexdigits = HEX_UPPER if upper else HEX_LOWER
    return ''.join(rng.choice(hexdigits) for _ in range(n))

def _format_uuid_fields(rng, variant=None, version=None, upper=False):
    # Fields: 8-4-4-4-12
    # time_low
    tl = _rand_hex_digits(rng, 8, upper)
    # time_mid
    tm = _rand_hex_digits(rng, 4, upper)

    # time_high_and_version: top 4 bits indicate version (1..5 typical, 4 for random)
    if version is None:
        version = rng.choice([1, 2, 3, 4, 5])
    # build 4 hex for this field
    # Ensure first nibble encodes version
    rest = _rand_hex_digits(rng, 3, upper)
    thv = (HEX_UPPER if upper else HEX_LOWER)[version] + rest

    # clock_seq_and_reserved: top bits indicate variant
    # RFC 4122 variant is binary 10xx (i.e., 8,9,a,b)
    if variant is None:
        variant = rng.choice(['rfc4122', 'ms', 'future'])
    if variant == 'rfc4122':
        first = rng.choice(['8', '9', 'a', 'b'] if not upper else ['8', '9', 'A', 'B'])
    elif variant == 'ms':
        # 0b110x -> c|d
        first = rng.choice(['c', 'd'] if not upper else ['C', 'D'])
    else:
        # 0b111x -> e|f
        first = rng.choice(['e', 'f'] if not upper else ['E', 'F'])
    csl = first + _rand_hex_digits(rng, 3, upper)

    # node
    node = _rand_hex_digits(rng, 12, upper)

    return f"{tl}-{tm}-{thv}-{csl}-{node}"

def _maybe_add_braces(rng, s):
    if rng.random() < 0.15:
        return "{" + s + "}"
    return s

def _maybe_uppercase(rng, s):
    if rng.random() < 0.3:
        return s.upper()
    return s

def _maybe_mixed_case(rng, s):
    if rng.random() < 0.1:
        out = []
        for ch in s:
            if ch in string.hexdigits:
                out.append(ch.upper() if rng.random() < 0.5 else ch.lower())
            else:
                out.append(ch)
        return ''.join(out)
    return s

def _maybe_include_prefix(rng, s):
    # Occasionally include a URN prefix; some parsers accept it, but canonical parser may not.
    # Keep probability low; canonical expected is plain 36 chars.
    if rng.random() < 0.05:
        return "urn:uuid:" + s
    return s

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose one of several interesting UUID profiles to exercise parser:
    profile = rng.choices(
        population=[
            'v4_rfc4122_lower',
            'v1_rfc4122_lower',
            'v3_rfc4122_upper',
            'v5_rfc4122_mixed',
            'nil',
            'brace_v4',
            'uppercase_v4',
        ],
        weights=[30, 15, 10, 10, 10, 15, 10],
        k=1,
    )[0]

    if profile == 'nil':
        # All zeros UUID
        base = "00000000-0000-0000-0000-000000000000"
    else:
        upper = profile in ('v3_rfc4122_upper', 'uppercase_v4')
        version = 4 if profile in ('v4_rfc4122_lower', 'brace_v4', 'uppercase_v4') else (
            1 if profile == 'v1_rfc4122_lower' else (3 if profile == 'v3_rfc4122_upper' else 5)
        )
        base = _format_uuid_fields(rng, variant='rfc4122', version=version, upper=upper)

    # Optional decorations/case tweaks
    if profile == 'brace_v4':
        base = _maybe_add_braces(rng, base)
    if profile == 'v5_rfc4122_mixed':
        base = _maybe_mixed_case(rng, base)
    if profile == 'uppercase_v4':
        base = base.upper()

    # Keep primarily canonical; small chance to prepend URN
    base = _maybe_include_prefix(rng, base)

    # Ensure resulting buffer length <= 4096 bytes
    s = base[:4096]
    return s.encode('ascii', errors='ignore')
